				SUBSTRING(cs.bitmapVirtual,3,1) = CAST(t.Rate AS BINARY(1))
				OR SUBSTRING(cs.bitmapVirtual,4,1) = CAST(t.Rate AS BINARY(1))
				OR SUBSTRING(cs.bitmapVirtual,5,1) = CAST(t.Rate AS BINARY(1))
				OR SUBSTRING(cs.bitmapVirtual,6,1) = CAST(t.Rate AS BINARY(1))	
				)
			)
		)
	